# Offline MCP catalog size, Windows equivalent of the guide's macOS/python3 recipe.
# Usage: pwsh -File measure-catalog.ps1 [path\to\jusprin-mcp.exe]
param([string]$Helper = "C:\src\JusPrin\build\src\Release\jusprin-mcp.exe")

$ErrorActionPreference = "Stop"
$dir = Join-Path $env:TEMP ("mcpmeas_" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $dir | Out-Null
try {
    $lines = @(
        '{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-06-18","capabilities":{},"clientInfo":{"name":"measure","version":"0"}}}',
        '{"jsonrpc":"2.0","method":"notifications/initialized"}',
        '{"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}'
    )
    $out = $lines | & $Helper --discovery (Join-Path $dir "none.json") 2>$null
    $total = 0
    $count = 0
    foreach ($line in $out) {
        try { $message = $line | ConvertFrom-Json } catch { continue }
        if ($message.id -ne 2 -or -not $message.result.tools) { continue }
        foreach ($tool in $message.result.tools) {
            $json = ($tool | ConvertTo-Json -Depth 40 -Compress)
            "{0,6}  {1}" -f $json.Length, $tool.name
            $total += $json.Length
            $count++
        }
    }
    "TOTAL {0} tools, {1} bytes, about {2} tokens" -f $count, $total, [int]($total / 4)
}
finally { Remove-Item -Recurse -Force $dir }

