    $out = $lines | & $Helper --discovery (Join-Path $dir "none.json") 2>$null
    $total = 0
    $count = 0
    foreach ($line in $out) {
        try { $message = $line | ConvertFrom-Json } catch { continue }
        if ($message.id -ne 2 -or -not $message.result.tools) { continue }
        foreach ($tool in $message.result.tools) {
            $json = ($tool | ConvertTo-Json -Depth 40 -Compress)
            "{0,6}  {1}" -f $json.Length, $tool.name
            $total += $json.Length
            $count++
        }
    }
    "TOTAL {0} tools, {1} bytes, about {2} tokens" -f $count, $total, [int]($total / 4)
}
finally { Remove-Item -Recurse -Force $dir }

