18	bool structurally_valid_schema(const json& schema)
19	{
20	    if (!schema.is_object() || schema.value("type", "") != "object" || !schema.contains("properties") ||
21	        !schema["properties"].is_object() || !schema.contains("required") || !schema["required"].is_array() ||
22	        schema.value("additionalProperties", true))
23	        return false;
24	    for (const json& required : schema["required"])
25	        if (!required.is_string() || !schema["properties"].contains(required.get<std::string>()))
26	            return false;
27	    for (const auto& property : schema["properties"].items())
28	        if (!property.value().is_object() || !property.value().contains("type") ||
29	            !property.value()["type"].is_string())
30	            return false;
31	    return true;
32	}
