76	// Time and material for one plate, read from the plate's own G-code result the
77	// same way Orca's preview and cost readouts do: volume per extruder times that
78	// filament's density and price. Nothing here is computed by JusPrin, so the
79	// card can never disagree with the number the slicer shows.
80	std::optional<SliceEstimate> estimate_of(const GCodeProcessorResult& result)
81	{
82	    SliceEstimate estimate;
83	    const auto& statistics = result.print_statistics;
84	    const auto& mode = statistics.modes[static_cast<std::size_t>(PrintEstimatedStatistics::ETimeMode::Normal)];
85	    estimate.print_time_seconds = mode.time > 0.f ? static_cast<std::uint32_t>(mode.time) : 0u;
86	
87	    double cost = 0.0;
88	    bool   every_filament_priced = true;
89	    for (const auto& [extruder, volume] : statistics.total_volumes_per_extruder) {
90	        // A slice that used an extruder Orca has no density for cannot be
91	        // weighed, and a partial weight presented as the total is worse than
92	        // no weight at all -- so the whole estimate goes.
93	        if (extruder >= result.filament_densities.size()) return std::nullopt;
94	        const double grams = volume * result.filament_densities[extruder] * 0.001;
95	        estimate.material_grams += grams;
96	        // A filament profile with no price reports zero, which is not a price.
97	        if (extruder < result.filament_costs.size() && result.filament_costs[extruder] > 0.f)
98	            cost += grams * result.filament_costs[extruder] * 0.001;
99	        else
100	            every_filament_priced = false;
101	    }
102	    // Money is the cost of the whole print or it is not shown. With one spool
103	    // priced and another not, a "total" would silently leave material out.
104	    estimate.has_cost      = every_filament_priced && cost > 0.0;
105	    estimate.material_cost = estimate.has_cost ? cost : 0.0;
106	    // A slice that produced no material is not an estimate worth a row.
107	    if (estimate.print_time_seconds == 0 && estimate.material_grams <= 0.0) return std::nullopt;
108	    return estimate;
109	}
