26	class ToolActivitySubscription
27	{
28	public:
29	    ToolActivitySubscription() = default;
30	    ToolActivitySubscription(const ToolActivitySubscription&) = delete;
31	    ToolActivitySubscription& operator=(const ToolActivitySubscription&) = delete;
32	    ToolActivitySubscription(ToolActivitySubscription&& other) noexcept : m_unsubscribe(std::move(other.m_unsubscribe)) {}
33	    ToolActivitySubscription& operator=(ToolActivitySubscription&& other) noexcept
34	    {
35	        if (this != &other) {
36	            reset();
37	            m_unsubscribe = std::move(other.m_unsubscribe);
38	        }
39	        return *this;
40	    }
41	    ~ToolActivitySubscription() { reset(); }
42	
43	    void reset()
44	    {
45	        if (m_unsubscribe) {
46	            auto unsubscribe = std::move(m_unsubscribe);
47	            unsubscribe();
48	        }
49	    }
50	
51	    explicit operator bool() const { return static_cast<bool>(m_unsubscribe); }
52	
53	private:
54	    explicit ToolActivitySubscription(std::function<void()> unsubscribe) : m_unsubscribe(std::move(unsubscribe)) {}
55	    std::function<void()> m_unsubscribe;
56	
57	    friend class ToolExecutionCoordinator;
58	};
59	
60	// Pump pacing belongs to deterministic test presentation, not to an adapter's
61	// untrusted ToolRequest or to public tool metadata.
62	struct ToolExecutionPacing
63	{
64	    int ticks{1};
65	};
66	
67	class ToolExecutionCoordinator
68	{
69	public:
70	    // Invoked after every observable activity change with the updated record.
71	    using ActivityCallback = std::function<void(const ToolActivity&)>;
72	
73	    struct ExtensionResult
74	    {
75	        bool                     handled{false};
76	        std::string              result_json;
77	        std::optional<ToolError> error;
78	    };
79	    // Typed native extensions still execute inside this coordinator and its
80	    // approval/state machine. The host uses this for durable manufacturing
81	    // records; future MCP adapters use the same seam, never a WebView path.
82	    using ExtensionExecutor = std::function<ExtensionResult(ToolHandler, const ToolActivity&)>;
83	
84	    explicit ToolExecutionCoordinator(Workspace::IWorkspace& workspace,
85	                                      const ToolRegistry& registry = ToolRegistry::instance());
86	    ~ToolExecutionCoordinator();
87	
88	    ToolExecutionCoordinator(const ToolExecutionCoordinator&) = delete;
89	    ToolExecutionCoordinator& operator=(const ToolExecutionCoordinator&) = delete;
90	
91	    ToolActivitySubscription subscribe(ActivityCallback listener);
92	    void set_extension_executor(ExtensionExecutor executor) { m_extension_executor = std::move(executor); }
93	
94	    // The store behind the intent and plan tools. The owner holds project
95	    // storage, so it supplies this; without it those tools report the
96	    // operation unavailable rather than pretending to record anything.
97	    void set_product_state(IProductState* state) { m_product_state = state; }
98	
99	    // Action IDs default to a process-local counter; an owner with persisted
100	    // state injects its own allocator so IDs stay unique across restarts.
101	    void set_action_id_allocator(std::function<std::string()> allocator) { m_action_id_allocator = std::move(allocator); }
102	
103	    // Resolves an attachment ID to the absolute path of its stored blob. The
104	    // owner (which holds project storage) provides this so import arguments
105	    // stay opaque IDs — no machine-specific path is persisted or shown.
106	    void set_attachment_path_resolver(std::function<std::string(const std::string&)> resolver)
107	    {
108	        m_attachment_path_resolver = std::move(resolver);
109	    }
110	
111	    // Drops every record. For project replacement: the records belong to the
112	    // previous project session and any persisted history keeps its own copy.
113	    void clear() { m_activities.clear(); }
114	    // Chat deletion may forget completed records, never in-flight work.
115	    void forget_terminal_activities(const std::vector<std::string>& message_ids);
116	
117	    // Creates a Pending record stamped with the current workspace session and
118	    // revision. Read-only actions are approved immediately by policy; every
119	    // other class waits for a user decision. Returns the new record.
120	    const ToolActivity& propose(const ToolRequest& request, const std::string& correlation_id,
121	                                ToolExecutionPacing pacing = {}, ToolSource source = ToolSource::Agent);
122	
123	    // User decisions. Each returns true only when it changed the record's
124	    // state, so a resent decision (reconnect, reload) can never run an action
125	    // twice or resurrect a terminal record.
126	    bool approve(const std::string& action_id);
127	    bool reject(const std::string& action_id);
128	    bool cancel(const std::string& action_id);
129	
130	    // Advances every Running activity by one deterministic tick: progress
131	    // first, then the native command on the final tick. The owner paces this
132	    // from a timer; tests call it directly.
133	    void pump();
134	
135	    bool any_running() const;
136	
137	    const std::vector<ToolActivity>& activities() const { return m_activities; }
138	    const ToolActivity*              find(const std::string& action_id) const;
139	
140	private:
141	    ToolActivity* find_mutable(const std::string& action_id);
142	    void          start_running(ToolActivity& activity);
143	    void          execute(ToolActivity& activity);
144	    void          fail(ToolActivity& activity, std::string code, std::string message, std::string details_json = "{}");
145	    void          notify(const ToolActivity& activity);
146	    void          invalidate_pending(const Workspace::WorkspaceChanged& change);
147	
148	    struct ObserverState
149	    {
150	        std::uint64_t                             next_id{1};
151	        bool                                      alive{true};
152	        std::map<std::uint64_t, ActivityCallback> observers;
153	    };
154	
155	    Workspace::IWorkspace&           m_workspace;
156	    const ToolRegistry&               m_registry;
157	    Workspace::WorkspaceSubscription m_workspace_subscription;
158	    std::shared_ptr<ObserverState>    m_observers;
159	    IProductState*                   m_product_state{nullptr};
160	    // The slice_start call behind the run now in flight, so the slicing
161	    // section can say which handle a reader is watching.
162	    std::string                      m_slice_handle;
163	    ExtensionExecutor                m_extension_executor;
164	    std::function<std::string()>     m_action_id_allocator;
165	    std::function<std::string(const std::string&)> m_attachment_path_resolver;
166	    std::vector<ToolActivity>        m_activities;
167	    std::uint64_t                    m_next_action_id{1};
168	    std::uint64_t                    m_last_invalidating_revision{0};
169	};
