1	// State-machine, approval-policy, idempotency, staleness, and execution
2	// contract tests for the ToolExecutionCoordinator against the fake
3	// workspace. Every command outcome is checked in both directions: success
4	// implies the workspace changed, and refusal or failure implies it did not.
5	// GUI-free.
6	
7	#include <catch2/catch_all.hpp>
8	
9	#include "slic3r/GUI/JusPrin/Agent/ToolExecutionCoordinator.hpp"
10	#include "slic3r/GUI/JusPrin/Mcp/McpProtocol.hpp"
11	#include "../jusprin_support/FakeProductState.hpp"
12	#include "../jusprin_support/FakeWorkspace.hpp"
13	
14	#include <nlohmann/json.hpp>
15	
16	#include <filesystem>
17	#include <fstream>
