46	struct Harness
47	{
48	    Workspace::FakeWorkspace  workspace;
49	    ToolExecutionCoordinator  coordinator;
50	    std::vector<ToolActivity> events;
51	    ToolActivitySubscription  subscription;
52	
53	    Harness() : workspace(one_plate_snapshot()), coordinator(workspace)
54	    {
55	        subscription = coordinator.subscribe([this](const ToolActivity& activity) { events.push_back(activity); });
56	    }
57	
58	    Workspace::ObjectId cube_id() const { return workspace.snapshot().plates.at(0).objects.at(0).id; }
59	
60	    std::size_t object_count() const
61	    {
62	        std::size_t count = 0;
63	        for (const Workspace::WorkspacePlate& plate : workspace.snapshot().plates)
64	            count += plate.objects.size();
65	        return count;
66	    }
