68	    ToolRequest duplicate_cube_request() const
69	    {
70	        ToolRequest request;
71	        request.tool           = "duplicate_object";
72	        request.arguments_json = json{{"sessionId", std::to_string(workspace.snapshot().session.value())},
73	                                      {"objectId", std::to_string(cube_id().value())}}
74	                                     .dump();
75	        return request;
76	    }
77	
78	    void pump_to_completion(const std::string& action_id, int limit = 1000)
79	    {
80	        while (!tool_state_terminal(coordinator.find(action_id)->state) && limit-- > 0)
81	            coordinator.pump();
82	    }
83	
84	    std::vector<ToolState> states_of(const std::string& action_id) const
85	    {
86	        std::vector<ToolState> states;
87	        for (const ToolActivity& event : events)
88	            if (event.action_id == action_id)
89	                states.push_back(event.state);
