96	TEST_CASE("approval policy follows the handoff", "[tools][policy]")
97	{
98	    // Read-only actions run without approval; every durable mutation asks
99	    // first; destructive actions may never use a remembered approval.
100	    STATIC_CHECK(!approval_required(ActionClass::ReadOnly));
101	    STATIC_CHECK(approval_required(ActionClass::Mutation));
102	    STATIC_CHECK(approval_required(ActionClass::Destructive));
103	    STATIC_CHECK(!remembered_approval_allowed(ActionClass::Destructive));
104	    STATIC_CHECK(!remembered_approval_allowed(ActionClass::ReadOnly));
105	
106	    // The computation-only exemption lifts the card from a mutation and from
107	    // nothing else: a destructive action keeps its card whatever it declares.
108	    STATIC_CHECK(!approval_required(ActionClass::Mutation, true));
109	    STATIC_CHECK(approval_required(ActionClass::Mutation, false));
110	    STATIC_CHECK(approval_required(ActionClass::Destructive, true));
111	    STATIC_CHECK(!approval_required(ActionClass::ReadOnly, true));
112	
113	    // Exactly which shipped tools claim it, so adding one is a visible diff
114	    // here. slice_start and activity_cancel join plan_set when they land.
115	    std::vector<std::string> exempt;
116	    for (const ToolDefinition& definition : ToolRegistry::instance().definitions()) {
117	        INFO(definition.name);
118	        if (definition.computation_only)
119	            exempt.push_back(definition.name);
120	        CHECK(approval_required(definition.action_class, definition.computation_only) ==
121	              (definition.action_class != ActionClass::ReadOnly && !definition.computation_only));
122	    }
123	    CHECK(exempt == std::vector<std::string>{"plan_set"});
124	}
