126	TEST_CASE("Settings approval captures the preview and rejects invalid or stale patches", "[tools][settings]")
127	{
128	    Harness h;
129	    auto request = [&](json changes) {
130	        const auto snapshot = h.workspace.snapshot();
131	        return ToolRequest{"settings_apply_patch", json{{"changes", changes}, {"expectedSessionId", std::to_string(snapshot.session.value())},
132	                                                       {"expectedRevision", snapshot.revision}}.dump()};
133	    };
134	    auto bad = h.coordinator.propose(request({{"wall_loops", 4}, {"brim_width", -1}}), "bad");
135	    REQUIRE(bad.state == ToolState::Failed);
136	    REQUIRE(bad.error->code == "invalid_setting_value");
137	    REQUIRE(json::parse(bad.error->details_json)["issues"][0]["key"] == "brim_width");
138	    REQUIRE(h.workspace.read_settings({"wall_loops"}).items[0].value == "2");
139	    REQUIRE(h.states_of(bad.action_id) == std::vector<ToolState>{ToolState::Failed});
140	
141	    auto pending = h.coordinator.propose(request({{"wall_loops", 4}}), "pending");
142	    REQUIRE(pending.state == ToolState::Pending);
143	    REQUIRE(json::parse(pending.arguments_json)["confirmedChanges"][0] == json{{"key", "wall_loops"}, {"before", "2"}, {"after", "4"}});
144	    REQUIRE(pending.title == "Change 1 process settings: wall_loops");
145	    SECTION("reject") { REQUIRE(h.coordinator.reject(pending.action_id)); }
146	    SECTION("cancel") { REQUIRE(h.coordinator.cancel(pending.action_id)); }
147	    SECTION("setting event") {
148	        h.workspace.set_setting_for_testing("brim_width", "7");
149	        REQUIRE(h.coordinator.find(pending.action_id)->error->code == "stale_revision");
150	    }
151	    SECTION("replacement") {
152	        h.workspace.replace_project(one_plate_snapshot());
153	        REQUIRE(h.coordinator.find(pending.action_id)->error->code == "stale_revision");
154	    }
155	    SECTION("unannounced edit") {
156	        h.workspace.set_setting_for_testing("wall_loops", "3", false);
157	        REQUIRE(h.coordinator.approve(pending.action_id));
158	        h.pump_to_completion(pending.action_id);
159	        REQUIRE(h.coordinator.find(pending.action_id)->error->code == "stale_workspace");
