51	    ToolActivitySubscription  subscription;
52	
53	    Harness() : workspace(one_plate_snapshot()), coordinator(workspace)
54	    {
55	        subscription = coordinator.subscribe([this](const ToolActivity& activity) { events.push_back(activity); });
56	    }
