# M1 eval over MCP against the live app: slice the plate, then report on it.
# Usage: pwsh -File m1-eval.ps1 <data dir with jusprin/mcp.json>
param([string]$DataDir = "C:\Users\guitest\AppData\Local\Temp\claude\m1mcp")

$ErrorActionPreference = "Stop"
$disc = Join-Path $DataDir "jusprin\mcp.json"
$deadline = (Get-Date).AddSeconds(180)
while (-not (Test-Path $disc) -and (Get-Date) -lt $deadline) { Start-Sleep -Seconds 1 }
if (-not (Test-Path $disc)) { throw "discovery not published under $DataDir" }
$url = (Get-Content $disc -Raw | ConvertFrom-Json -Depth 100).url
$id = 0

function Call([string]$method, [string]$paramsJson) {
    $script:id++
    $h = @{ "Accept" = "application/json, text/event-stream"; "MCP-Method" = $method; "MCP-Protocol-Version" = "2026-07-28" }
    if ($paramsJson -match '"name"\s*:\s*"([^"]+)"') { $h["MCP-Name"] = $Matches[1] }
    $meta = '"_meta":{"io.modelcontextprotocol/protocolVersion":"2026-07-28","io.modelcontextprotocol/clientCapabilities":{}}'
    $params = if ($paramsJson) { "{$paramsJson,$meta}" } else { "{$meta}" }
    $body = '{"jsonrpc":"2.0","id":' + $script:id + ',"method":"' + $method + '","params":' + $params + '}'
    Invoke-RestMethod -Uri $url -Method Post -Headers $h -ContentType "application/json" -Body $body -TimeoutSec 180
}

function CallTool([string]$name, [string]$argumentsJson = "{}") {
    $result = Call "tools/call" ('"name":"' + $name + '","arguments":' + $argumentsJson)
    if ($result.result.isError) { throw "$name failed: " + ($result.result.content[0].text) }
    return $result.result.structuredContent
}

"== catalog =="
$list = Call "tools/list" $null
($list.result.tools | ForEach-Object { $_.name }) -join ", "

"== before =="
$before = CallTool "workspace_inspect" '{"sections":["summary","slicing"]}'
"plates=$($before.plateCount) objects=$($before.objectCount) sliced=$($before.slicing.plates[0].sliced) running=$($before.slicing.running)"

"== slice =="
$started = CallTool "slice_start" "{}"
"handle=$($started.handle) started=$($started.started) running=$($started.slicing.running)"

$deadline = (Get-Date).AddSeconds(300)
do {
    Start-Sleep -Seconds 2
    $state = CallTool "workspace_inspect" '{"sections":["slicing"]}'
} while ($state.slicing.running -and (Get-Date) -lt $deadline)
"running=$($state.slicing.running) sliced=$($state.slicing.plates[0].sliced)"

"== report =="
$report = CallTool "slice_report" '{"sections":["summary","findings","material"]}'
"valid=$($report.valid)"
if ($report.valid) {
    $minutes = [int]($report.summary.printTimeSeconds / 60)
    "print time: $minutes min ($($report.summary.printTimeSeconds) s)"
    "filament:   $([math]::Round($report.summary.totalGrams,2)) g, cost known: $($report.summary.hasCost)"
    foreach ($f in $report.summary.filaments) {
        "  extruder $($f.extruder): $([math]::Round($f.lengthMm/1000,2)) m, $([math]::Round($f.grams,2)) g"
    }
    "findings:   $($report.findings.items.Count) (conflict: '$($report.findings.conflict)', outside bed: $($report.findings.toolpathOutsideBed))"
    foreach ($item in $report.findings.items) { "  [$(if ($item.critical) {'critical'} else {'warning'})] $($item.message)" }
    "material:   $($report.material.filamentChanges) filament changes, $($report.material.extruderChanges) tool changes"
}

"== intent and plan =="
$intent = CallTool "intent_update" '{"fields":[{"field":"useCase","value":"decorative"},{"field":"maxPrintTime","question":"How long may this take?"}]}'
"intent fields: $($intent.intent.fields.Count), open: $($intent.intent.openQuestions -join ',')"

