97	                                                      ToolExecutionPacing pacing, ToolSource source)
98	{
99	    const Workspace::WorkspaceSnapshot snapshot = m_workspace.snapshot();
100	    const ToolDefinition* definition = m_registry.find(request.tool);
101	
102	    ToolActivity activity;
103	    activity.action_id         = m_action_id_allocator ? m_action_id_allocator() : "t-" + std::to_string(m_next_action_id++);
104	    activity.correlation_id    = correlation_id;
105	    activity.source            = source;
106	    activity.server            = kServerName;
107	    activity.tool              = request.tool;
108	    activity.arguments_json    = request.arguments_json;
109	    activity.session           = snapshot.session.value();
110	    activity.expected_revision = snapshot.revision;
111	    activity.progress_total    = pacing.ticks > 0 ? pacing.ticks : 1;
112	
113	    if (definition != nullptr) {
114	        activity.title             = definition->title;
115	        activity.action_class      = definition->action_class;
116	        activity.requires_approval = m_registry.requires_approval(*definition, request.arguments_json);
117	    } else {
118	        activity.title = "Unknown tool request";
119	    }
120	
121	    m_activities.emplace_back(std::move(activity));
122	    ToolActivity& stored = m_activities.back();
123	
124	    if (definition == nullptr) {
125	        fail(stored, "unknown_tool", "This build has no tool named \"" + request.tool + "\".");
126	        return stored;
127	    }
128	
129	    ToolValidationResult validation = m_registry.validate_call(*definition, request.arguments_json);
130	    if (!validation.valid()) {
131	        fail(stored, validation.error->code, validation.error->message);
132	        return stored;
133	    }
134	    stored.arguments_json = std::move(validation.arguments_json);
135	    stored.title = m_registry.approval_title(*definition, stored.arguments_json);
136	
137	    if (definition->handler == ToolHandler::SettingsApplyPatch) {
138	        auto arguments = json::parse(stored.arguments_json);
139	        if (arguments["expectedSessionId"] != std::to_string(snapshot.session.value()) || arguments["expectedRevision"] != snapshot.revision) {
140	            fail(stored, "stale_workspace", "The workspace changed. Read and preview again.", stale_settings_details(arguments, snapshot).dump());
141	            return stored;
142	        }
143	        const auto preview = m_workspace.preview_settings(settings_patch(arguments));
144	        if (!preview.valid) {
145	            const auto& issue = preview.issues.at(0);
146	            fail(stored, issue.code, issue.message, settings_preview_result(preview, snapshot).dump());
147	            return stored;
148	        }
149	        arguments["confirmedChanges"] = json::array();
150	        for (const auto& change : Workspace::settings_confirmation(preview))
151	            arguments["confirmedChanges"].push_back({{"key", change.key}, {"before", change.before}, {"after", change.after}});
152	        stored.arguments_json = arguments.dump();
153	    }
154	
155	    notify(stored);
156	    if (!stored.requires_approval)
157	        start_running(stored);
158	    return stored;
